def init_mapping(self):
    import heapq
    from collections import deque

    N = self.num_qubits
    mapping = [-1] * N
    reverse = [-1] * N
    used = set()
    placed = set()

    qig = self.qubit_interaction_graph
    backend = self.backend
    centrality = self.physical_centrality
    phys_range = len(self.distance_matrix)

    def place(lq, pq):
        mapping[lq] = pq
        reverse[pq] = lq
        used.add(pq)
        placed.add(lq)

    def pick_central_unused():
        best, best_score = None, -1.0
        for p in range(phys_range):
            if p in used:
                continue
            sc = centrality.get(p, 0.0)
            if sc > best_score:
                best_score = sc
                best = p
        if best is not None:
            return best
        for p in range(N):
            if p not in used:
                return p
        return None

    def pick_adjacent_unused(anchor):
        best, best_score = None, -1.0
        for nb in backend.get(anchor, []):
            if nb in used:
                continue
            sc = centrality.get(nb, 0.0)
            if sc > best_score:
                best_score = sc
                best = nb
        if best is not None:
            return best
        visited = {anchor}
        bq = deque([anchor])
        while bq:
            cur = bq.popleft()
            for nb in backend.get(cur, []):
                if nb in visited:
                    continue
                visited.add(nb)
                if nb not in used:
                    return nb
                bq.append(nb)
        return None

    edges = []
    for q1 in qig:
        for q2, w in qig[q1].items():
            if q1 < q2:
                edges.append((w, q1, q2))
    edges.sort(key=lambda x: -x[0])

    heap = []

    def add_frontier(lq):
        for nb, w in qig.get(lq, {}).items():
            if nb not in placed:
                heapq.heappush(heap, (-w, lq, nb))

    def grow():
        while heap:
            _, pq, uq = heapq.heappop(heap)
            if uq in placed:
                continue
            new_phys = pick_adjacent_unused(mapping[pq])
            if new_phys is None:
                return
            place(uq, new_phys)
            add_frontier(uq)

    for (w, q1, q2) in edges:
        if q1 in placed or q2 in placed:
            continue
        p1 = pick_central_unused()
        if p1 is None:
            break
        used.add(p1)
        p2 = pick_adjacent_unused(p1)
        used.discard(p1)
        place(q1, p1)
        add_frontier(q1)
        if p2 is not None:
            place(q2, p2)
            add_frontier(q2)
        grow()

    for q in qig:
        if 0 <= q < N and q not in placed:
            p = pick_central_unused()
            if p is None:
                break
            place(q, p)
            add_frontier(q)
            grow()

    for q in range(N):
        if mapping[q] == -1 and q not in used:
            place(q, q)
    for q in range(N):
        if mapping[q] != -1:
            continue
        for p in range(N):
            if p not in used:
                place(q, p)
                break

    self.mapping_dict = mapping
    self.reverse_mapping_dict = reverse
    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    N = self.num_qubits

    self.mapping_dict = [-1] * N
    self.reverse_mapping_dict = [-1] * N

    if self.access2q is not None:
        active_logicals = set()
        for g, qs in self.access2q.items():
            if len(qs) == 2:
                active_logicals.add(qs[0])
                active_logicals.add(qs[1])
    else:
        active_logicals = set()
        for g, qs in self.access.items():
            if len(qs) == 2:
                active_logicals.add(qs[0])
                active_logicals.add(qs[1])

    activity = {}
    for q in active_logicals:
        if q in self.logical_activity:
            activity[q] = self.logical_activity[q]
        else:
            neigh = self.qubit_interaction_graph.get(q, {})
            activity[q] = sum(neigh.values())

    ranked_logicals = sorted(
        active_logicals,
        key=lambda q: (-activity.get(q, 0), q),
    )

    physical_ids = [p for p in range(N) if p in self.physical_centrality]
    if not physical_ids:
        physical_ids = list(range(N))

    ranked_physicals = sorted(
        physical_ids,
        key=lambda p: (-self.physical_centrality.get(p, 0.0), p),
    )

    used_physical = set()
    placed_logical = set()

    pair_count = min(len(ranked_logicals), len(ranked_physicals))
    for i in range(pair_count):
        lq = ranked_logicals[i]
        pq = ranked_physicals[i]
        if lq >= N or pq >= N:
            continue
        self.mapping_dict[lq] = pq
        self.reverse_mapping_dict[pq] = lq
        used_physical.add(pq)
        placed_logical.add(lq)

    free_physicals = [p for p in range(N) if p not in used_physical]
    free_idx = 0
    for lq in range(N):
        if lq in placed_logical:
            continue
        if self.mapping_dict[lq] != -1:
            continue
        if lq not in used_physical and lq < N:
            chosen = lq if (lq not in used_physical) else None
        else:
            chosen = None
        if chosen is None or chosen in used_physical:
            while free_idx < len(free_physicals) and free_physicals[free_idx] in used_physical:
                free_idx += 1
            if free_idx >= len(free_physicals):
                break
            chosen = free_physicals[free_idx]
            free_idx += 1
        self.mapping_dict[lq] = chosen
        self.reverse_mapping_dict[chosen] = lq
        used_physical.add(chosen)

    if -1 in self.mapping_dict:
        remaining_phys = [p for p in range(N) if p not in used_physical]
        rp_iter = iter(remaining_phys)
        for lq in range(N):
            if self.mapping_dict[lq] == -1:
                try:
                    pq = next(rp_iter)
                except StopIteration:
                    break
                while pq in used_physical:
                    try:
                        pq = next(rp_iter)
                    except StopIteration:
                        pq = None
                        break
                if pq is None:
                    break
                self.mapping_dict[lq] = pq
                self.reverse_mapping_dict[pq] = lq
                used_physical.add(pq)

    if -1 in self.mapping_dict:
        used = set(p for p in self.mapping_dict if p != -1)
        spare = [p for p in range(N) if p not in used]
        si = 0
        for lq in range(N):
            if self.mapping_dict[lq] == -1:
                if si < len(spare):
                    self.mapping_dict[lq] = spare[si]
                    self.reverse_mapping_dict[spare[si]] = lq
                    si += 1

    if self.use_isl:
        try:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        except Exception:
            pass

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import heapq

    N = self.num_qubits
    num_physical = len(self.distance_matrix)

    logical_qubits_in_access = set()
    for gate_id, qubits in self.access.items():
        for q in qubits:
            logical_qubits_in_access.add(q)
    for q in self.qubit_interaction_graph.keys():
        logical_qubits_in_access.add(q)

    logical_to_place = [q for q in logical_qubits_in_access if 0 <= q < N]

    placed = {}
    used = set()

    mapping_list = [-1] * N
    reverse_list = [-1] * N

    if not logical_to_place:
        for i in range(N):
            mapping_list[i] = i
            reverse_list[i] = i
        self.mapping_dict = mapping_list
        self.reverse_mapping_dict = reverse_list
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    def activity_of(q):
        return self.logical_activity.get(q, 0)

    anchor_logical = max(logical_to_place, key=lambda q: (activity_of(q), -q))

    physical_candidates = list(range(num_physical))
    if not physical_candidates:
        for i in range(N):
            mapping_list[i] = i
            reverse_list[i] = i
        self.mapping_dict = mapping_list
        self.reverse_mapping_dict = reverse_list
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    def centrality_of(p):
        return self.physical_centrality.get(p, 0.0)

    anchor_physical = max(physical_candidates, key=lambda p: (centrality_of(p), -p))

    placed[anchor_logical] = anchor_physical
    used.add(anchor_physical)

    def cost_on_physical(logical_q, phys_p):
        total = 0.0
        neighbors = self.qubit_interaction_graph.get(logical_q, {})
        for partner, w in neighbors.items():
            if partner in placed:
                partner_phys = placed[partner]
                if 0 <= partner_phys < len(self.distance_matrix) and 0 <= phys_p < len(self.distance_matrix):
                    total += w * self.distance_matrix[phys_p][partner_phys]
                else:
                    total += w * 1e9
        return total

    def placed_partner_weight(logical_q):
        total = 0.0
        neighbors = self.qubit_interaction_graph.get(logical_q, {})
        for partner, w in neighbors.items():
            if partner in placed:
                total += w
        return total

    pq = []
    counter = 0
    anchor_neighbors = self.qubit_interaction_graph.get(anchor_logical, {})
    for nb, w in anchor_neighbors.items():
        if nb in placed:
            continue
        if not (0 <= nb < N):
            continue
        heapq.heappush(pq, (-w, counter, nb))
        counter += 1

    while pq:
        neg_priority, _, logical_q = heapq.heappop(pq)
        if logical_q in placed:
            continue

        current_weight = placed_partner_weight(logical_q)
        if -neg_priority < current_weight:
            heapq.heappush(pq, (-current_weight, counter, logical_q))
            counter += 1
            continue

        free_phys = [p for p in range(num_physical) if p not in used]
        if not free_phys:
            break

        best_p = None
        best_cost = None
        for p in free_phys:
            c = cost_on_physical(logical_q, p)
            tiebreak_centrality = -centrality_of(p)
            key = (c, tiebreak_centrality, p)
            if best_cost is None or key < best_cost:
                best_cost = key
                best_p = p

        placed[logical_q] = best_p
        used.add(best_p)

        for nb, w in self.qubit_interaction_graph.get(logical_q, {}).items():
            if nb in placed:
                continue
            if not (0 <= nb < N):
                continue
            new_weight = placed_partner_weight(nb) + w
            heapq.heappush(pq, (-new_weight, counter, nb))
            counter += 1

    remaining_logical = [q for q in logical_to_place if q not in placed]
    remaining_physical = [p for p in range(num_physical) if p not in used]

    for lq in remaining_logical:
        if not remaining_physical:
            break
        if lq in placed:
            continue
        if lq < num_physical and lq not in used:
            chosen = lq
            remaining_physical.remove(lq)
        else:
            chosen = remaining_physical.pop(0)
        placed[lq] = chosen
        used.add(chosen)

    all_logical = list(range(N))
    unplaced_logical = [q for q in all_logical if q not in placed]
    remaining_physical = [p for p in range(N) if p not in used]

    for lq in unplaced_logical:
        if lq < N and lq not in used:
            chosen = lq
            if lq in remaining_physical:
                remaining_physical.remove(lq)
        elif remaining_physical:
            chosen = remaining_physical.pop(0)
        else:
            continue
        placed[lq] = chosen
        used.add(chosen)

    for lq, pq_phys in placed.items():
        if 0 <= lq < N and 0 <= pq_phys < N:
            mapping_list[lq] = pq_phys

    free_phys_final = [p for p in range(N) if p not in used]
    missing_logical = [i for i in range(N) if mapping_list[i] == -1]
    for lq in missing_logical:
        if free_phys_final:
            p = free_phys_final.pop(0)
            mapping_list[lq] = p
            used.add(p)
        else:
            mapping_list[lq] = lq

    seen = set()
    duplicates = []
    for i, p in enumerate(mapping_list):
        if p in seen or p < 0 or p >= N:
            duplicates.append(i)
        else:
            seen.add(p)
    free_phys_final = [p for p in range(N) if p not in seen]
    for i in duplicates:
        if free_phys_final:
            mapping_list[i] = free_phys_final.pop(0)
            seen.add(mapping_list[i])
        else:
            mapping_list[i] = i

    for i in range(N):
        p = mapping_list[i]
        if 0 <= p < N:
            reverse_list[p] = i

    self.mapping_dict = mapping_list
    self.reverse_mapping_dict = reverse_list

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

