def init_mapping(self):
    import numpy as np

    N = self.num_qubits

    mapping = list(range(N))
    reverse = list(range(N))

    try:
        # Logical Laplacian from weighted qubit interaction graph
        L_log = np.zeros((N, N), dtype=float)
        for q1, neighbors in self.qubit_interaction_graph.items():
            if not (0 <= q1 < N):
                continue
            for q2, w in neighbors.items():
                if not (0 <= q2 < N) or q1 == q2:
                    continue
                L_log[q1][q2] = -float(w)
        for i in range(N):
            L_log[i][i] = -L_log[i].sum()

        # Physical Laplacian from deduped undirected coupling edges
        L_phys = np.zeros((N, N), dtype=float)
        seen_edges = set()
        for edge in self.backend_connections:
            if len(edge) != 2:
                continue
            u, v = edge
            if not (0 <= u < N) or not (0 <= v < N) or u == v:
                continue
            ek = (u, v) if u < v else (v, u)
            if ek in seen_edges:
                continue
            seen_edges.add(ek)
            L_phys[u][v] = -1.0
            L_phys[v][u] = -1.0
        for i in range(N):
            L_phys[i][i] = -L_phys[i].sum()

        # Symmetric eigendecomposition (eigh returns ascending eigenvalues)
        _, v_log = np.linalg.eigh(L_log)
        _, v_phys = np.linalg.eigh(L_phys)

        def pick_coords(V):
            cols = V.shape[1]
            if cols >= 3:
                return V[:, 1:3]
            if cols == 2:
                return np.column_stack([V[:, 1], np.zeros(V.shape[0])])
            return np.zeros((V.shape[0], 2))

        log_coords = pick_coords(v_log)
        phys_coords = pick_coords(v_phys)

        active = [q for q in range(N) if self.logical_activity.get(q, 0) > 0]
        active.sort(key=lambda q: -self.logical_activity.get(q, 0))
        active_set = set(active)
        inactive = [q for q in range(N) if q not in active_set]
        order = active + inactive

        mapping = [-1] * N
        reverse = [-1] * N
        used_physical = [False] * N

        for lq in order:
            lc0 = log_coords[lq, 0]
            lc1 = log_coords[lq, 1]
            best_pq = -1
            best_dist = float('inf')
            for pq in range(N):
                if used_physical[pq]:
                    continue
                d0 = lc0 - phys_coords[pq, 0]
                d1 = lc1 - phys_coords[pq, 1]
                d = d0 * d0 + d1 * d1
                if d < best_dist:
                    best_dist = d
                    best_pq = pq
