def init_mapping(self):
    from collections import defaultdict

    N = self.num_qubits
    dist = self.distance_matrix

    weights = defaultdict(int)
    logical_set = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                continue
            key = (a, b) if a < b else (b, a)
            weights[key] += 1
            logical_set.add(a)
            logical_set.add(b)
        elif len(qubits) == 1:
            logical_set.add(qubits[0])

    logical_set = {l for l in logical_set if 0 <= l < N}

    neighbors = defaultdict(dict)
    degree = defaultdict(int)
    for (a, b), w in weights.items():
        neighbors[a][b] = w
        neighbors[b][a] = w
        degree[a] += w
        degree[b] += w

    centrality = []
    for p in range(N):
        s = 0
        for q in range(N):
            s += dist[p][q]
        centrality.append(s)

    mapping = [-1] * N
    reverse = [-1] * N
    used_phys = set()
    placed_log = set()

    def partial_cost_for(log_q, phys_q):
        c = 0
        for other_log, w in neighbors[log_q].items():
            if other_log in placed_log:
                c += w * dist[phys_q][mapping[other_log]]
        return c

    sorted_logicals = sorted(logical_set, key=lambda l: -degree[l])

    if sorted_logicals:
        first_log = sorted_logicals[0]
        best_phys = min(range(N), key=lambda p: centrality[p])
        mapping[first_log] = best_phys
        reverse[best_phys] = first_log
        used_phys.add(best_phys)
        placed_log.add(first_log)

        for log_q in sorted_logicals[1:]:
            best_p = None
            best_c = None
            for p in range(N):
                if p in used_phys:
                    continue
                c = 0
                for other_log, w in neighbors[log_q].items():
                    if other_log in placed_log:
                        c += w * dist[p][mapping[other_log]]
                if best_c is None or c < best_c:
                    best_c = c
                    best_p = p
            if best_p is None:
                break
            mapping[log_q] = best_p
            reverse[best_p] = log_q
            used_phys.add(best_p)
            placed_log.add(log_q)

    free_phys = [p for p in range(N) if p not in used_phys]
    fi = 0
    for l in range(N):
        if mapping[l] == -1:
            if l not in used_phys and reverse[l] == -1:
                mapping[l] = l
                reverse[l] = l
                used_phys.add(l)
            else:
                while fi < len(free_phys) and free_phys[fi] in used_phys:
                    fi += 1
                if fi < len(free_phys):
                    p = free_phys[fi]
                    mapping[l] = p
                    reverse[p] = l
                    used_phys.add(p)
                    fi += 1

    remaining = [p for p in range(N) if p not in used_phys]
    ri = 0
    for l in range(N):
        if mapping[l] == -1:
            if ri < len(remaining):
                p = remaining[ri]
                mapping[l] = p
                reverse[p] = l
                ri += 1

    def total_cost():
        c = 0
        for (a, b), w in weights.items():
            if mapping[a] != -1 and mapping[b] != -1:
                c += w * dist[mapping[a]][mapping[b]]
        return c

    def swap_delta(la, lb):
        pa = mapping[la]
        pb = mapping[lb]
        delta = 0
        for other, w in neighbors[la].items():
            if other == lb:
                continue
            po = mapping[other]
            if po == -1:
                continue
            delta += w * (dist[pb][po] - dist[pa][po])
        for other, w in neighbors[lb].items():
            if other == la:
                continue
            po = mapping[other]
            if po == -1:
                continue
            delta += w * (dist[pa][po] - dist[pb][po])
        return delta

    active_logicals = [l for l in logical_set if mapping[l] != -1]

    max_iters = max(1, min(200, 4 * len(active_logicals) + 10))
    for _ in range(max_iters):
        best_delta = 0
        best_pair = None
        for i in range(len(active_logicals)):
            la = active_logicals[i]
            for j in range(i + 1, len(active_logicals)):
                lb = active_logicals[j]
                if lb not in neighbors[la] and not any(o in neighbors[la] or o == la for o in neighbors[lb]):
                    pass
                d = swap_delta(la, lb)
                if d < best_delta - 1e-12:
                    best_delta = d
                    best_pair = (la, lb)
        if best_pair is None:
            break
        la, lb = best_pair
        pa, pb = mapping[la], mapping[lb]
        mapping[la], mapping[lb] = pb, pa
        reverse[pa], reverse[pb] = lb, la

    for l in range(N):
        if mapping[l] == -1:
            for p in range(N):
                if reverse[p] == -1:
                    mapping[l] = p
                    reverse[p] = l
                    break

    self.mapping_dict = mapping
    self.reverse_mapping_dict = reverse
    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

