            if best_p is None:
                best_p = candidates[0]
            placed[log_q] = best_p

        for log_q, phys_q in placed.items():
            if log_q not in logical_to_physical and phys_q not in used_phys:
                logical_to_physical[log_q] = phys_q
                used_phys.add(phys_q)

    final_mapping = [-1] * N
    final_used = [False] * N

    for log_q, phys_q in logical_to_physical.items():
        if 0 <= log_q < N and 0 <= phys_q < N and not final_used[phys_q] and final_mapping[log_q] == -1:
            final_mapping[log_q] = phys_q
            final_used[phys_q] = True

    for i in range(N):
        if final_mapping[i] == -1 and not final_used[i]:
            final_mapping[i] = i
            final_used[i] = True

    unused = [p for p in range(N) if not final_used[p]]
    idx = 0
    for i in range(N):
        if final_mapping[i] == -1:
            final_mapping[i] = unused[idx]
            final_used[unused[idx]] = True
            idx += 1

    self.mapping_dict = final_mapping
    self.reverse_mapping_dict = [0] * N
    for log_q in range(N):
        self.reverse_mapping_dict[self.mapping_dict[log_q]] = log_q

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import collections

    N = self.num_qubits

    interactions = {}
    active_logicals = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                continue
            key = (a, b) if a < b else (b, a)
            interactions[key] = interactions.get(key, 0) + 1
            active_logicals.add(a)
            active_logicals.add(b)

    log_adj = collections.defaultdict(dict)
    for (a, b), w in interactions.items():
        log_adj[a][b] = w
        log_adj[b][a] = w

    phys_adj = collections.defaultdict(set)
    for edge in self.backend_connections:
        u, v = edge[0], edge[1]
        phys_adj[u].add(v)
        phys_adj[v].add(u)

    INF = 10 ** 9

    def bfs_distances(adj, source, allowed):
        dist = {source: 0}
        q = collections.deque([source])
        while q:
            u = q.popleft()
            for v in adj.get(u, ()):
                if v in allowed and v not in dist:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    def find_endpoints(adj, nodes):
        if not nodes:
            return None, None
        start = next(iter(nodes))
        d1 = bfs_distances(adj, start, nodes)
        far1 = max(d1, key=d1.get) if d1 else start
        d2 = bfs_distances(adj, far1, nodes)
        far2 = max(d2, key=d2.get) if d2 else far1
        return far1, far2

    def bisect_physical(nodes):
        nodes = set(nodes)
        if len(nodes) <= 1:
            return set(nodes), set()
        a, b = find_endpoints(phys_adj, nodes)
        if a is None or b is None or a == b:
            lst = sorted(nodes)
            half = (len(lst) + 1) // 2
            return set(lst[:half]), set(lst[half:])
        da = bfs_distances(phys_adj, a, nodes)
        db = bfs_distances(phys_adj, b, nodes)
        target_a = (len(nodes) + 1) // 2
        scored = sorted(nodes, key=lambda n: (da.get(n, INF) - db.get(n, INF), n))
        return set(scored[:target_a]), set(scored[target_a:])

    def bisect_logical(nodes):
        nodes = set(nodes)
        if len(nodes) <= 1:
            return set(nodes), set()
        a, b = find_endpoints(log_adj, nodes)
        if a is None or b is None or a == b:
            lst = sorted(nodes)
            half = (len(lst) + 1) // 2
            return set(lst[:half]), set(lst[half:])
        target_a = (len(nodes) + 1) // 2
        target_b = len(nodes) - target_a
        side_a = {a}
        side_b = {b}
        remaining = nodes - {a, b}
        while remaining:
            a_full = len(side_a) >= target_a
            b_full = len(side_b) >= target_b
            best_node = None
            best_score = -INF
            best_side = 'a'
            for n in remaining:
                wa = 0
                wb = 0
                nbrs = log_adj[n]
                for x, w in nbrs.items():
                    if x in side_a:
                        wa += w
                    elif x in side_b:
                        wb += w
                if a_full:
                    score = wb
                    side = 'b'
                elif b_full:
                    score = wa
                    side = 'a'
                else:
                    if wa >= wb:
                        score = wa - wb
                        side = 'a'
                    else:
                        score = wb - wa
                        side = 'b'
                if score > best_score:
                    best_score = score
                    best_node = n
                    best_side = side
            if best_side == 'a':
                side_a.add(best_node)
            else:
                side_b.add(best_node)
            remaining.discard(best_node)
        return side_a, side_b

    assignment = {}

    def recurse(log_nodes, phys_nodes):
        log_nodes = set(log_nodes)
        phys_nodes = set(phys_nodes)
        if not log_nodes or not phys_nodes:
            return
        if len(log_nodes) == 1:
            l = next(iter(log_nodes))
            best_p = None
            best_ecc = None
            for p in phys_nodes:
                d = bfs_distances(phys_adj, p, phys_nodes)
                ecc = max(d.values()) if d else 0
                if best_ecc is None or ecc < best_ecc:
                    best_ecc = ecc
                    best_p = p
            if best_p is None:
                best_p = next(iter(phys_nodes))
            assignment[l] = best_p
            return

        la, lb = bisect_logical(log_nodes)
        pa, pb = bisect_physical(phys_nodes)

        need_a = len(la)
        all_p = pa | pb
        if len(pa) != need_a and all_p:
            seed = next(iter(pa)) if pa else next(iter(all_p))
            dc = bfs_distances(phys_adj, seed, all_p)
            sorted_p = sorted(all_p, key=lambda x: (dc.get(x, INF), x))
            pa = set(sorted_p[:need_a])
            pb = all_p - pa

        recurse(la, pa)
        recurse(lb, pb)

    all_phys = set(range(N))
    recurse(active_logicals, all_phys)

    self.mapping_dict = [0] * N
    self.reverse_mapping_dict = [0] * N
    used_phys = set()
    placed_logicals = set()

    for l, p in assignment.items():
        if p is None:
            continue
        if 0 <= l < N and 0 <= p < N and p not in used_phys:
            self.mapping_dict[l] = p
            self.reverse_mapping_dict[p] = l
            used_phys.add(p)
            placed_logicals.add(l)

    free_phys = [p for p in range(N) if p not in used_phys]
    free_idx = 0
    for l in range(N):
        if l in placed_logicals:
            continue
        if l not in used_phys:
            self.mapping_dict[l] = l
            self.reverse_mapping_dict[l] = l
            used_phys.add(l)
        else:
            while free_idx < len(free_phys) and free_phys[free_idx] in used_phys:
                free_idx += 1
            if free_idx < len(free_phys):
                p = free_phys[free_idx]
                free_idx += 1
                self.mapping_dict[l] = p
                self.reverse_mapping_dict[p] = l
                used_phys.add(p)

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    from collections import defaultdict, deque
    import math
    import random as _rnd

    N = self.num_qubits

    self.mapping_dict = list(range(N))
    self.reverse_mapping_dict = list(range(N))

    qig = defaultdict(lambda: defaultdict(float))
    logical_nodes = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            q1, q2 = qubits[0], qubits[1]
            if 0 <= q1 < N and 0 <= q2 < N and q1 != q2:
                qig[q1][q2] += 1.0
                qig[q2][q1] += 1.0
                logical_nodes.add(q1)
                logical_nodes.add(q2)

    if not logical_nodes:
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    labels = {q: q for q in logical_nodes}
    rng = _rnd.Random(42)
    nodes = list(logical_nodes)
    for _it in range(20):
        rng.shuffle(nodes)
        changed = False
        for q in nodes:
            nbrs = qig.get(q, {})
            if not nbrs:
                continue
            weight_per_label = defaultdict(float)
            for nb, w in nbrs.items():
                weight_per_label[labels[nb]] += w
            if not weight_per_label:
                continue
            max_w = max(weight_per_label.values())
            best = [lab for lab, w in weight_per_label.items() if w == max_w]
            new_lab = min(best)
            if new_lab != labels[q]:
                labels[q] = new_lab
                changed = True
        if not changed:
            break

    communities = defaultdict(list)
    for q, lab in labels.items():
        communities[lab].append(q)
    community_list = sorted(communities.values(), key=lambda c: -len(c))

    phys_adj = defaultdict(set)
    phys_nodes = set()
    for (a, b) in self.backend_connections:
        if a == b:
            continue
        phys_adj[a].add(b)
        phys_adj[b].add(a)
        phys_nodes.add(a)
        phys_nodes.add(b)
    phys_nodes = {p for p in phys_nodes if 0 <= p < N}
    phys_degree = {p: len(phys_adj[p]) for p in phys_nodes}

    def dist(p1, p2):
        if p1 == p2:
            return 0
        try:
            d = self.distance_matrix[p1][p2]
            if d and d > 0:
                return d
        except Exception:
            pass
        visited = {p1: 0}
        dq = deque([p1])
        while dq:
            x = dq.popleft()
            for y in phys_adj.get(x, ()):
                if y not in visited:
                    visited[y] = visited[x] + 1
                    if y == p2:
                        return visited[y]
                    dq.append(y)
        return 10 ** 6

    used_phys = set()
    logical_to_physical = {}

    for comm in community_list:
        size = len(comm)
        available = [p for p in phys_nodes if p not in used_phys]
        if not available:
            break
        available.sort(key=lambda p: (-phys_degree.get(p, 0), p))
        seed = available[0]

        region = []
        visited = {seed}
        frontier = deque([seed])
        while frontier and len(region) < size:
            node = frontier.popleft()
            if node in used_phys:
                continue
            region.append(node)
            nbs = [nb for nb in phys_adj[node]
                   if nb not in visited and nb not in used_phys and nb in phys_nodes]
            nbs.sort(key=lambda p: (-phys_degree.get(p, 0), p))
            for nb in nbs:
                visited.add(nb)
                frontier.append(nb)

        if len(region) < size:
            for p in available:
                if p not in region and p not in used_phys:
                    region.append(p)
                    if len(region) >= size:
                        break
        region = region[:size]
        if not region:
            continue

        comm_set = set(comm)
        intra_weight = {}
        for q in comm:
            w = 0.0
            for nb, ww in qig.get(q, {}).items():
                if nb in comm_set:
                    w += ww
            intra_weight[q] = w
        ordered_logical = sorted(comm, key=lambda q: (-intra_weight.get(q, 0.0), q))

        region_by_deg = sorted(region, key=lambda p: (-phys_degree.get(p, 0), p))
        placed = {}
        anchor_log = ordered_logical[0]
        anchor_phys = region_by_deg[0]
        placed[anchor_log] = anchor_phys

        for log_q in ordered_logical[1:]:
            partners = [(nb, w) for nb, w in qig.get(log_q, {}).items() if nb in placed]
            taken = set(placed.values())
            candidates = [p for p in region if p not in taken]
            if not candidates:
                break
            best_p = None
            best_cost = float('inf')
            for p in candidates:
                if partners:
                    cost = 0.0
                    for partner_log, w in partners:
                        d = dist(p, placed[partner_log])
                        cost += w * math.log(1.0 + d)
                else:
                    cost = -phys_degree.get(p, 0)
                if cost < best_cost:
                    best_cost = cost
                    best_p = p
            if best_p is None:
                best_p = candidates[0]
            placed[log_q] = best_p

        for log_q, phys_q in placed.items():
            if log_q not in logical_to_physical and phys_q not in used_phys:
                logical_to_physical[log_q] = phys_q
                used_phys.add(phys_q)

    final_mapping = [-1] * N
    final_used = [False] * N

    for log_q, phys_q in logical_to_physical.items():
        if 0 <= log_q < N and 0 <= phys_q < N and not final_used[phys_q] and final_mapping[log_q] == -1:
            final_mapping[log_q] = phys_q
            final_used[phys_q] = True

    for i in range(N):
        if final_mapping[i] == -1 and not final_used[i]:
            final_mapping[i] = i
            final_used[i] = True

    unused = [p for p in range(N) if not final_used[p]]
    idx = 0
    for i in range(N):
        if final_mapping[i] == -1:
            final_mapping[i] = unused[idx]
            final_used[unused[idx]] = True
            idx += 1

    self.mapping_dict = final_mapping
    self.reverse_mapping_dict = [0] * N
    for log_q in range(N):
        self.reverse_mapping_dict[self.mapping_dict[log_q]] = log_q

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    from collections import Counter, defaultdict

    N = self.num_qubits
    self.mapping_dict = [-1] * N
    self.reverse_mapping_dict = [-1] * N

    # 1. Collect 2-qubit interactions from self.access
    pair_count = Counter()
    logical_qubits = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                logical_qubits.add(a)
                continue
            logical_qubits.add(a); logical_qubits.add(b)
            key = (a, b) if a < b else (b, a)
            pair_count[key] += 1
        elif len(qubits) == 1:
            logical_qubits.add(qubits[0])

    # Per-logical interaction weights (for greedy cost later)
    logical_neighbors = defaultdict(Counter)
    for (a, b), c in pair_count.items():
        logical_neighbors[a][b] += c
        logical_neighbors[b][a] += c

    # 2. Physical edges (undirected)
    phys_edges = set()
    for (pa, pb) in self.backend_connections:
        if pa == pb:
            continue
        phys_edges.add((pa, pb) if pa < pb else (pb, pa))

    used_phys = set()

    def place(L, P):
        if L < 0 or L >= N or P < 0 or P >= N:
            return False
        if self.mapping_dict[L] != -1 or P in used_phys:
            return False
        self.mapping_dict[L] = P
        self.reverse_mapping_dict[P] = L
        used_phys.add(P)
        return True

    def free_neighbor(P):
        best = None
        best_deg = -1
        for q in self.backend[P]:
            if q not in used_phys:
                deg = sum(1 for r in self.backend[q] if r not in used_phys)
                if deg > best_deg:
                    best_deg = deg
                    best = q
        return best

    def best_free_edge():
        best = None
        best_score = -1
        for (pa, pb) in phys_edges:
            if pa in used_phys or pb in used_phys:
                continue
            score = 0
            for q in self.backend[pa]:
                if q not in used_phys and q != pb:
                    score += 1
            for q in self.backend[pb]:
                if q not in used_phys and q != pa:
                    score += 1
            if score > best_score:
                best_score = score
                best = (pa, pb)
        return best

    # 3. Heavy-edge direct matching: process logical pairs by descending frequency
    sorted_pairs = sorted(pair_count.items(), key=lambda kv: -kv[1])
    for (L1, L2), _freq in sorted_pairs:
        if L1 >= N or L2 >= N:
            continue
        p1 = self.mapping_dict[L1]
        p2 = self.mapping_dict[L2]
        if p1 != -1 and p2 != -1:
            continue
        if p1 != -1 and p2 == -1:
            nb = free_neighbor(p1)
            if nb is not None:
                place(L2, nb)
            continue
        if p2 != -1 and p1 == -1:
            nb = free_neighbor(p2)
            if nb is not None:
                place(L1, nb)
            continue
        # neither placed: pin onto a physical edge
        edge = best_free_edge()
        if edge is not None:
            # Orient so the higher-degree logical goes to the higher-degree physical
            pa, pb = edge
            deg_a = sum(1 for r in self.backend[pa] if r not in used_phys and r != pb)
            deg_b = sum(1 for r in self.backend[pb] if r not in used_phys and r != pa)
            w1 = sum(logical_neighbors[L1].values())
            w2 = sum(logical_neighbors[L2].values())
            if (w1 >= w2) == (deg_a >= deg_b):
                place(L1, pa); place(L2, pb)
            else:
                place(L1, pb); place(L2, pa)

    # 4. Cheapest-slot greedy for remaining circuit qubits
    remaining = [L for L in logical_qubits if 0 <= L < N and self.mapping_dict[L] == -1]
    # Order by total interaction weight (heaviest first)
    remaining.sort(key=lambda L: -sum(logical_neighbors[L].values()))
    for L in remaining:
        partners = []
        for other, cnt in logical_neighbors[L].items():
            if 0 <= other < N and self.mapping_dict[other] != -1:
                partners.append((self.mapping_dict[other], cnt))
        best_P = None
        best_cost = float('inf')
        for P in range(N):
            if P in used_phys:
                continue
            if partners:
                cost = 0
                for (pp, cnt) in partners:
                    cost += cnt * self.distance_matrix[P][pp]
            else:
                cost = 0
            if cost < best_cost:
                best_cost = cost
                best_P = P
                if cost == 0 and not partners:
                    break
        if best_P is not None:
            place(L, best_P)

    # 5. Identity fallback for any logical qubit still unassigned
    for L in range(N):
        if self.mapping_dict[L] == -1:
            if L not in used_phys:
                place(L, L)
            else:
                for P in range(N):
                    if P not in used_phys:
                        place(L, P)
                        break

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import math
    from collections import defaultdict

    N = self.num_qubits

    # --- 1. Logical interaction graph (weighted by gate frequency) ---
    logical_adj = defaultdict(lambda: defaultdict(float))
    active_logical = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                continue
            logical_adj[a][b] += 1.0
            logical_adj[b][a] += 1.0
            active_logical.add(a)
            active_logical.add(b)

    # --- 2. Physical coupling graph ---
    physical_adj = defaultdict(set)
    if getattr(self, "backend", None) is not None:
        for p, nbrs in enumerate(self.backend):
            for q in nbrs:
                if p != q:
                    physical_adj[p].add(q)
                    physical_adj[q].add(p)
    if getattr(self, "backend_connections", None):
        for (p, q) in self.backend_connections:
            if p != q:
                physical_adj[p].add(q)
                physical_adj[q].add(p)

    # --- 3a. PageRank on logical graph ---
    def pagerank_weighted(nodes, adj_weighted, iters=60, damping=0.85):
        if not nodes:
            return {}
        n = len(nodes)
        pr = {u: 1.0 / n for u in nodes}
        out_w = {u: sum(adj_weighted[u].values()) for u in nodes}
        for _ in range(iters):
            new_pr = {u: (1.0 - damping) / n for u in nodes}
            dangling_mass = 0.0
            for u in nodes:
                if out_w[u] == 0.0:
                    dangling_mass += pr[u]
            for u in nodes:
                if out_w[u] > 0.0:
                    share = damping * pr[u] / out_w[u]
                    for v, w in adj_weighted[u].items():
                        if v in new_pr:
                            new_pr[v] += share * w
            if dangling_mass > 0.0:
                add = damping * dangling_mass / n
                for u in nodes:
                    new_pr[u] += add
            pr = new_pr
        return pr

    # --- 3b. PageRank on physical graph (unweighted) ---
    def pagerank_unweighted(nodes, adj_set, iters=60, damping=0.85):
        if not nodes:
            return {}
        n = len(nodes)
        pr = {u: 1.0 / n for u in nodes}
        deg = {u: len(adj_set[u]) for u in nodes}
        for _ in range(iters):
            new_pr = {u: (1.0 - damping) / n for u in nodes}
            dangling_mass = 0.0
            for u in nodes:
                if deg[u] == 0:
                    dangling_mass += pr[u]
            for u in nodes:
                if deg[u] > 0:
                    share = damping * pr[u] / deg[u]
                    for v in adj_set[u]:
                        if v in new_pr:
                            new_pr[v] += share
            if dangling_mass > 0.0:
                add = damping * dangling_mass / n
                for u in nodes:
                    new_pr[u] += add
            pr = new_pr
        return pr

    logical_nodes = list(active_logical)
    logical_pr = pagerank_weighted(logical_nodes, logical_adj)

    physical_nodes = list(range(N))
    physical_pr = pagerank_unweighted(physical_nodes, physical_adj)

    # --- 4. Rank orderings (desc by centrality; tie-break by degree then id) ---
    def logical_key(u):
        return (-logical_pr.get(u, 0.0),
                -sum(logical_adj[u].values()),
                u)

    def physical_key(p):
        return (-physical_pr.get(p, 0.0),
                -len(physical_adj[p]),
                p)

    logical_ranked = sorted(logical_nodes, key=logical_key)
    physical_ranked = sorted(physical_nodes, key=physical_key)

    # --- 5. Zip alignment for active logicals ---
    mapping = [-1] * N
    reverse = [-1] * N
    used_phys = set()

    for l, p in zip(logical_ranked, physical_ranked):
        if 0 <= l < N and p not in used_phys:
            mapping[l] = p
            reverse[p] = l
            used_phys.add(p)

    # --- 6. Identity fallback for any unmapped logicals ---
    remaining_phys = [p for p in range(N) if p not in used_phys]
    rp_iter = iter(remaining_phys)
    for l in range(N):
        if mapping[l] == -1:
            # prefer identity if physical l is still free
            if l < N and l not in used_phys:
                mapping[l] = l
                reverse[l] = l
                used_phys.add(l)
            else:
                try:
                    p = next(rp_iter)
                    while p in used_phys:
                        p = next(rp_iter)
                    mapping[l] = p
                    reverse[p] = l
                    used_phys.add(p)
                except StopIteration:
                    pass

    self.mapping_dict = mapping
    self.reverse_mapping_dict = reverse

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    from collections import defaultdict, deque
    import random as _rnd

    N = self.num_qubits

    self.mapping_dict = list(range(N))
    self.reverse_mapping_dict = list(range(N))

    qig = defaultdict(lambda: defaultdict(float))
    logical_nodes = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            q1, q2 = qubits[0], qubits[1]
            if 0 <= q1 < N and 0 <= q2 < N and q1 != q2:
                qig[q1][q2] += 1.0
                qig[q2][q1] += 1.0
                logical_nodes.add(q1)
                logical_nodes.add(q2)

    if not logical_nodes:
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    labels = {q: q for q in logical_nodes}
    rng = _rnd.Random(42)
    nodes = list(logical_nodes)
    for _it in range(20):
        rng.shuffle(nodes)
        changed = False
        for q in nodes:
            nbrs = qig.get(q, {})
            if not nbrs:
                continue
            weight_per_label = defaultdict(float)
            for nb, w in nbrs.items():
                weight_per_label[labels[nb]] += w
            if not weight_per_label:
                continue
            max_w = max(weight_per_label.values())
            best = [lab for lab, w in weight_per_label.items() if w == max_w]
            new_lab = min(best)
            if new_lab != labels[q]:
                labels[q] = new_lab
                changed = True
        if not changed:
            break

    communities = defaultdict(list)
    for q, lab in labels.items():
        communities[lab].append(q)
    community_list = sorted(communities.values(), key=lambda c: -len(c))

    phys_adj = defaultdict(set)
    phys_nodes = set()
    for (a, b) in self.backend_connections:
        if a == b:
            continue
        phys_adj[a].add(b)
        phys_adj[b].add(a)
        phys_nodes.add(a)
        phys_nodes.add(b)
    phys_nodes = {p for p in phys_nodes if 0 <= p < N}
    phys_degree = {p: len(phys_adj[p]) for p in phys_nodes}

    def dist(p1, p2):
        if p1 == p2:
            return 0
        try:
            d = self.distance_matrix[p1][p2]
            if d and d > 0:
                return d
        except Exception:
            pass
        visited = {p1: 0}
        dq = deque([p1])
        while dq:
            x = dq.popleft()
            for y in phys_adj.get(x, ()):
                if y not in visited:
                    visited[y] = visited[x] + 1
                    if y == p2:
                        return visited[y]
                    dq.append(y)
        return 10 ** 6

    LOOKAHEAD_ALPHA = 0.5

    used_phys = set()
    logical_to_physical = {}

    for comm in community_list:
        size = len(comm)
        available = [p for p in phys_nodes if p not in used_phys]
        if not available:
            break
        available.sort(key=lambda p: (-phys_degree.get(p, 0), p))
        seed = available[0]

        region = []
        visited = {seed}
        frontier = deque([seed])
        while frontier and len(region) < size:
            node = frontier.popleft()
            if node in used_phys:
                continue
            region.append(node)
            nbs = [nb for nb in phys_adj[node]
                   if nb not in visited and nb not in used_phys and nb in phys_nodes]
            nbs.sort(key=lambda p: (-phys_degree.get(p, 0), p))
            for nb in nbs:
                visited.add(nb)
                frontier.append(nb)

        if len(region) < size:
            for p in available:
                if p not in region and p not in used_phys:
                    region.append(p)
                    if len(region) >= size:
                        break
        region = region[:size]
        if not region:
            continue

        comm_set = set(comm)
        intra_weight = {}
        for q in comm:
            w = 0.0
            for nb, ww in qig.get(q, {}).items():
                if nb in comm_set:
                    w += ww
            intra_weight[q] = w
        ordered_logical = sorted(comm, key=lambda q: (-intra_weight.get(q, 0.0), q))

        region_by_deg = sorted(region, key=lambda p: (-phys_degree.get(p, 0), p))
        placed = {}
        anchor_log = ordered_logical[0]
        anchor_phys = region_by_deg[0]
        placed[anchor_log] = anchor_phys

        for log_q in ordered_logical[1:]:
            partners = [(nb, w) for nb, w in qig.get(log_q, {}).items() if nb in placed]
            unplaced_partners = [(nb, w) for nb, w in qig.get(log_q, {}).items()
                                 if nb in comm_set and nb not in placed and nb != log_q]
            taken = set(placed.values())
            candidates = [p for p in region if p not in taken]
            if not candidates:
                break

            best_p = None
            best_cost = float('inf')
            for p in candidates:
                cost = 0.0
                for partner_log, w in partners:
                    cost += w * dist(p, placed[partner_log])

                if unplaced_partners:
                    remaining = [r for r in candidates if r != p]
                    if remaining:
                        avg_d = sum(dist(p, r) for r in remaining) / len(remaining)
                        sum_unplaced_w = sum(w for _, w in unplaced_partners)
                        cost += LOOKAHEAD_ALPHA * sum_unplaced_w * avg_d

                if not partners and not unplaced_partners:
                    cost = -phys_degree.get(p, 0)

                if cost < best_cost:
                    best_cost = cost
                    best_p = p

            if best_p is None:
                best_p = candidates[0]
            placed[log_q] = best_p

        for log_q, phys_q in placed.items():
            if log_q not in logical_to_physical and phys_q not in used_phys:
                logical_to_physical[log_q] = phys_q
                used_phys.add(phys_q)

    final_mapping = [-1] * N
    final_used = [False] * N

    for log_q, phys_q in logical_to_physical.items():
        if 0 <= log_q < N and 0 <= phys_q < N and not final_used[phys_q] and final_mapping[log_q] == -1:
            final_mapping[log_q] = phys_q
            final_used[phys_q] = True

    for i in range(N):
        if final_mapping[i] == -1 and not final_used[i]:
            final_mapping[i] = i
            final_used[i] = True

    unused = [p for p in range(N) if not final_used[p]]
    idx = 0
    for i in range(N):
        if final_mapping[i] == -1:
            final_mapping[i] = unused[idx]
            final_used[unused[idx]] = True
            idx += 1

    self.mapping_dict = final_mapping
    self.reverse_mapping_dict = [0] * N
    for log_q in range(N):
        self.reverse_mapping_dict[self.mapping_dict[log_q]] = log_q

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)
